# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::LocalOutboxSource do
  # "Every outbox read and mark filters by company_id; company A's source never returns or marks company B's rows"
  it "company A's unsent_after returns none of company B's rows even when B's positions sit below, between and above A's" do
    company_a = create(:company)
    company_b = create(:company)
    generation = TimekeepingOwnership.current.generation
    payload_for = lambda do |company, entry_id|
      Timekeeping::SnapshotBatch::ENTRY_FIELDS.index_with { nil }
        .merge("id" => entry_id, "company_id" => company.id, "duration" => 60.0, "version" => 1)
    end
    # Positions come from one sequence shared by every company, so writing the
    # rows alternately interleaves the two companies' positions.
    write = lambda do |company, entry_id|
      Timekeeping::LocalOutboxEntry.create!(
        company_id: company.id, entry_id:, generation:, payload: payload_for.call(company, entry_id),
        created_at: Time.current
      ).outbox_position
    end
    b_positions = []
    a_positions = []
    b_positions << write.call(company_b, 9001)
    a_positions << write.call(company_a, 1001)
    b_positions << write.call(company_b, 9002)
    a_positions << write.call(company_a, 1002)
    b_positions << write.call(company_b, 9003)

    rows = described_class.new(company_id: company_a.id).unsent_after(0, 100)

    expect(rows.map { |row| row.fetch("outbox_position") }).to eq(a_positions)
    expect(rows.map { |row| row.fetch("entry").fetch("company_id") }.uniq).to eq([company_a.id])
    expect(rows.map { |row| row.fetch("outbox_position") } & b_positions).to be_empty
    expect(described_class.new(company_id: company_b.id).unsent_after(0, 100).map { |row| row.fetch("outbox_position") })
      .to eq(b_positions)
  end
end

RSpec.describe Timekeeping::LocalOutboxSource do
  # "Every outbox read and mark filters by company_id; company A's source never returns or marks company B's rows"
  # "`mark_sent` sets `sent_at` by `company_id` and the exact positions, never by entry id."
  it "company A's mark_sent given company B's positions leaves every B row unsent" do
    company_a = create(:company)
    company_b = create(:company)
    generation = TimekeepingOwnership.current.generation
    write = lambda do |company, entry_id|
      payload = Timekeeping::SnapshotBatch::ENTRY_FIELDS.index_with { nil }
        .merge("id" => entry_id, "company_id" => company.id, "duration" => 30.0, "version" => 1)
      Timekeeping::LocalOutboxEntry.create!(
        company_id: company.id, entry_id:, generation:, payload:, created_at: Time.current
      ).outbox_position
    end
    b_first = write.call(company_b, 9101)
    a_only = write.call(company_a, 1101)
    b_second = write.call(company_b, 9102)
    sent_at = ->(position) { Timekeeping::LocalOutboxEntry.find(position).sent_at }

    source_a = described_class.new(company_id: company_a.id)
    source_a.mark_sent([b_first, b_second])

    expect(sent_at.call(b_first)).to be_nil
    expect(sent_at.call(b_second)).to be_nil
    expect(sent_at.call(a_only)).to be_nil

    source_a.mark_sent([b_first, a_only, b_second])

    expect(sent_at.call(a_only)).to be_present
    expect(sent_at.call(b_first)).to be_nil
    expect(sent_at.call(b_second)).to be_nil
    expect(described_class.new(company_id: company_b.id).unsent_after(0, 100).map { |row| row.fetch("outbox_position") })
      .to eq([b_first, b_second])
  end
end
